import React, { useState, useEffect, useContext } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import api from '../services/api';
import { AuthContext } from '../context/AuthContext';
import { Layout, BookOpen, CheckCircle, Lock, TrendingUp } from 'lucide-react';

const Dashboard = () => {
  const { user, setUser } = useContext(AuthContext);
  const [topics, setTopics] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  const refreshUserProgress = async () => {
    try {
      const response = await api.get('/auth/profile');
      setUser(response.data);
    } catch (error) {
      console.error('Error refreshing profile', error);
    }
  };

  useEffect(() => {
    const loadData = async () => {
      try {
        const [topicsRes] = await Promise.all([
          api.get('/topics'),
          refreshUserProgress()
        ]);
        setTopics(topicsRes.data);
      } catch (error) {
        console.error('Error loading dashboard data', error);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  if (loading) return <div className="flex justify-center items-center h-64">Loading Dashboard...</div>;

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold">Welcome, {user?.username}! 👋</h1>
          <p className="text-slate-500 dark:text-slate-400">Continue your journey to Java mastery.</p>
        </div>
        <div className="flex items-center gap-4 bg-white dark:bg-slate-800 p-4 rounded-xl border border-slate-200 dark:border-slate-700">
          <TrendingUp className="text-primary-600" />
          <div>
            <p className="text-xs text-slate-500 uppercase font-bold">Overall Progress</p>
            <p className="text-lg font-bold">
              {topics.length > 0
                ? `${Math.round((Object.keys(user?.progress || {}).length / topics.length) * 100)}%`
                : '0%'}
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {topics.map(topic => (
          <div key={topic.id} className="card group hover:border-primary-500 transition-all cursor-pointer" onClick={() => navigate(`/topic/${topic.id}`)}>
            <div className="flex justify-between items-start mb-4">
              <div className="p-2 bg-primary-50 dark:bg-primary-900/30 rounded-lg text-primary-600">
                <BookOpen size={24} />
              </div>
              {user?.progress?.[topic.id] === 100 && (
                <CheckCircle className="text-green-500" size={20} />
              )}
            </div>
            <h3 className="text-xl font-bold mb-2 group-hover:text-primary-600 transition-colors">{topic.title}</h3>
            <p className="text-slate-600 dark:text-slate-400 text-sm mb-6 line-clamp-2">{topic.description}</p>
            <div className="flex justify-between items-center">
              <span className="text-xs font-medium px-2 py-1 bg-slate-100 dark:bg-slate-700 rounded text-slate-500">
                {topic.id.replace('-', ' ').toUpperCase()}
              </span>
              <Link
                to={`/topic/${topic.id}`}
                className="text-sm font-bold text-primary-600 group-hover:underline"
              >
                Explore →
              </Link>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Dashboard;
